 public GameView(Context c,WorldState s,Host h){this(c,s,h,true);} public GameView(Context c,WorldState s,Host h,boolean ready){super(c);CatCameraDirector.resetForNewView();state=s;simulationReady=ready;host=h;density=getResources().getDisplayMetrics().density;p.setAntiAlias(false);p.setFilterBitmap(false);bg.setAntiAlias(false);bg.setFilterBitmap(false);bg.setColorFilter(worldPaletteFilter());text.setAntiAlias(true);text.setTypeface(Typeface.create(Typeface.SANS_SERIF,Typeface.NORMAL));assets=new AssetManifest(c);logicalWallNow=Math.max(System.currentTimeMillis(),Math.max(state.lastOpenedAt,state.lastSimulatedAt));StateInvariantChecker.normalize(state,logicalWallNow);if(ready)syncRealClock(logicalWallNow);setFocusable(true);} public void replaceState(WorldState next,boolean ready){if(next==null)return;long n=Math.max(System.currentTimeMillis(),Math.max(next.lastOpenedAt,next.lastSimulatedAt));StateInvariantChecker.normalize(next,n);state=next;simulationReady=ready;logicalWallNow=n;activeBacklogMs=0;CatCameraDirector.resetForNewView();visualCameraReady=false;loadedArea="";if(ready)syncRealClock(n);postInvalidate();} public void setSimulationReady(boolean ready){simulationReady=ready;activeBacklogMs=0;postInvalidate();} public boolean isSimulationReady(){return simulationReady;} public void setDivineVisualPresence(boolean present){divineVisualPresence=present;postInvalidate();}
 @Override protected void onDraw(Canvas c){long now=System.nanoTime(),wall=System.currentTimeMillis();lastFrameGapMs=Math.max(0L,(now-lastFrame)/1000000L);float dt=Math.min(.05f,Math.max(0f,lastFrameGapMs/1000f));lastFrame=now;if(lastFrameGapMs>=DISTURBANCE_NOTICE_MS)beginDisturbance(wall);Throwable failure=null;try{update(dt);}catch(Throwable e){failure=e;}if(failure==null){try{render(c);if(firstWorldFrameReported)dispatchAudio(wall);}catch(Throwable e){failure=e;}}if(failure==null&&BuildConfig.DEBUG&&!debugAreaKey.isEmpty()&&!debugCaptureReadyLogged){debugCaptureReadyLogged=true;android.util.Log.i("VNF","VISUAL_CAPTURE_READY biome="+debugAreaKey);}if(failure==null&&!firstWorldFrameReported){firstWorldFrameReported=true;post(()->{try{host.onFirstWorldFrame();}catch(Throwable ignored){}});}boolean forcedVeil=wall<devVeilUntil;if(failure!=null){lastRenderError=failure;lastFailureAt=wall;consecutiveFailures++;beginDisturbance(wall);tryAutoMaintenance(wall);try{drawWorldDisturbance(c,wall,severeDisturbance(wall,true));}catch(Throwable ignored){drawEmergencyVeil(c);}}else{lastRenderError=null;if(activeBacklogMs>=DISTURBANCE_NOTICE_MS)beginDisturbance(wall);boolean stabilizing=forcedVeil||activeBacklogMs>500||(disturbanceStartedAt>0&&wall-disturbanceStartedAt<MIN_DISTURBANCE_DISPLAY_MS);if(stabilizing){drawWorldDisturbance(c,wall,forcedVeil&&devVeilSevere);}else{if(devVeilUntil>0){devVeilUntil=0;devVeilSevere=false;}if(disturbanceStartedAt>0){recoveryNoticeUntil=Math.max(recoveryNoticeUntil,wall+RECOVERY_NOTICE_MS);disturbanceStartedAt=0;consecutiveFailures=0;}if(wall<recoveryNoticeUntil)drawRecoveryNotice(c,wall);if(wall<haruVisionUntil)drawHaruVision(c);} }postInvalidateDelayed(failure!=null?250:33);}
