 private ColorFilter worldPaletteFilter(){float saturation=1.20f,contrast=1.08f,offset=128f*(1f-contrast);ColorMatrix sat=new ColorMatrix();sat.setSaturation(saturation);ColorMatrix con=new ColorMatrix(new float[]{contrast,0,0,0,offset,0,contrast,0,0,offset,0,0,contrast,0,offset,0,0,0,1,0});sat.postConcat(con);return new ColorMatrixColorFilter(sat);}private ColorFilter areaPaletteFilter(String area){float sat="garden".equals(area)?1.24f:"grove".equals(area)?1.15f:"lakeside".equals(area)?1.17f:1.20f,contrast="grove".equals(area)?1.11f:"lakeside".equals(area)?1.06f:1.08f;float r="home".equals(area)?1.045f:"lakeside".equals(area)?.965f:"grove".equals(area)?.94f:1.02f,g="garden".equals(area)?1.045f:"grove".equals(area)?1.025f:1.0f,b="lakeside".equals(area)?1.065f:"home".equals(area)?.955f:"grove".equals(area)?.98f:1.0f;float off=128f*(1f-contrast);String phase=state.environment==null?"DAY":state.environment.dayPhase(state.worldMinutes);if("EVENING".equals(phase)){r+=.025f;b-=.02f;}else if("NIGHT".equals(phase)){r-=.035f;b+=.045f;sat-=.04f;}else if("MORNING".equals(phase)){r+=.015f;g+=.008f;}ColorMatrix cm=new ColorMatrix();cm.setSaturation(sat);ColorMatrix tone=new ColorMatrix(new float[]{r*contrast,0,0,0,off,0,g*contrast,0,0,off,0,0,b*contrast,0,off,0,0,0,1,0});cm.postConcat(tone);return new ColorMatrixColorFilter(cm);}
