  p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.1f*density);p.setColor(Color.argb((int)(120*fade),205,226,214));c.drawRoundRect(x,y,x+maxW,y+boxH,15*density,15*density,p);p.setStyle(Paint.Style.FILL);
  text.setTextSize(10.5f*density);text.setColor(Color.argb((int)(210*fade),171,203,192));c.drawText(DisplayNames.girl(state).toUpperCase(java.util.Locale.ROOT)+" · TỰ NÓI",x+20*density,y+20*density,text);
  text.setTextSize(15*density);text.setColor(Color.argb((int)(255*fade),242,235,216));float ty=y+43*density;for(String ln:lines){c.drawText(ln,x+20*density,ty,text);ty+=lineH;}
  if(exprH>0){text.setTextSize(11*density);text.setColor(Color.argb((int)(185*fade),164,190,184));c.drawText("〈"+haruSpeechExpression+"〉",x+20*density,ty+2*density,text);}
