 @Override public boolean onTouchEvent(MotionEvent e){MinimalHudLayout.Layout u=MinimalHudLayout.forScreen(getWidth(),getHeight(),density);int hit=u.hit(e.getX(),e.getY());if(e.getAction()==MotionEvent.ACTION_DOWN){hudPressed=hit;postInvalidate();return true;}if(e.getAction()==MotionEvent.ACTION_CANCEL){hudPressed=MinimalHudLayout.NONE;postInvalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){int pressed=hudPressed;hudPressed=MinimalHudLayout.NONE;postInvalidate();if(hit==pressed&&pressed!=MinimalHudLayout.NONE){performClick();if(pressed==MinimalHudLayout.GOD){host.onGod();return true;}if(pressed==MinimalHudLayout.CHAT){host.onTalk();return true;}if(pressed==MinimalHudLayout.MIC){long n=System.currentTimeMillis();boolean dbl=n-lastVoiceTap<350;lastVoiceTap=n;host.onVoiceTap(dbl);return true;}}return true;}return true;}
